                      F (Z_to_bv 64 P_A_PREP_AVAIL) fc None m2 (seg_rom asegs))) ->
    evt asegs Q (MS (mkR rax (Z_to_bv 64 spa) gp tp y0 y1 y2 sp (Z_to_bv 64 spa) (Z_to_bv 64 (b + 56)) (Z_to_bv 64 xl) (Z_to_bv 64 (b + 8))
