  (* [comment removed for export] *)
  Lemma prep_midP : forall (Q : machine_state -> Prop) (m : mem) (P : list mbe) (xl sl op : Z) (j0 j32 j128 j160 h32 h80 : list byte)
      (rax gp tp y0 y1 y2 a5 a6 a7 y3 y4 y5 y6 : word) (F : bvmap 5 word) fc,
    es = P ++ [(xl, sl)] -> 0 <= op -> sl < op + n -> op <= sl ->
    AMBraw m b es xl insz op op ->
    rw_cells asegs m spa (prep_locals1 b n ff j0 j32 j128 j160) ->
    rw_cells asegs m ff (prep_ff1 ff spa fp h32 h80) ->
    mem_inv asegs m ->
    (forall (m2 : mem) (j32' : list byte) (a0x a1x a4x : word),
       munch [(spa, spa + 184); (b + 24, b + 64)]%Z m m2 -> wmono asegs m m2 -> mem_inv asegs m2 ->
       rw_cells asegs m2 spa (prep_locals1 b n ff j0 j32' j128 j160) ->
       rw_cells asegs m2 ff (prep_ff1 ff spa fp h32 h80) ->
       AMBraw m2 b es xl insz op sl ->
       evt asegs Q (prep_atJ sp spa b ff res (insz + (sl - op)) (n - (sl - op)) 1 rax gp tp y0 y1 y2 a0x a1x (Z_to_bv 64 (sl - op))
                      (Z_to_bv 64 n) a4x a5 a6 a7 (Z_to_bv 64 (ff + 64)) y3 y4 y5 y6 F fc m2)) ->
    evt asegs Q (MS (mkR rax (Z_to_bv 64 spa) gp tp y0 y1 y2 sp (Z_to_bv 64 spa) (Z_to_bv 64 sl) (Z_to_bv 64 sl) (Z_to_bv 64 (sl - op))
                        (Z_to_bv 64 n) (Z_to_bv 64 op) a5 a6 a7 (Z_to_bv 64 (ff + 72)) (Z_to_bv 64 (Z.shiftr ff 3 + 2147450880)) (Z_to_bv 64 res)
                        (Z_to_bv 64 b) (Z_to_bv 64 (insz + (sl - op))) (Z_to_bv 64 (Z.shiftr (b + 48) 3 + 2147450880)) (Z_to_bv 64 2147450880)
                        (Z_to_bv 64 (b + 48)) (Z_to_bv 64 ff) (Z_to_bv 64 (ff + 64)) y3 y4 y5 y6)
